using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class F1FinalCheck {
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit required");var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var near=GameObject.Find("AE_OvergrownFactoryTerrain").GetComponent<Terrain>();var mid=GameObject.Find("FW_WildernessTerrain").GetComponent<Terrain>();var far=GameObject.Find("FW_DistantHorizonTerrain").GetComponent<Terrain>();float H(Terrain t,float x,float z)=>t.transform.position.y+t.terrainData.GetInterpolatedHeight((x-t.transform.position.x)/t.terrainData.size.x,(z-t.transform.position.z)/t.terrainData.size.z);var errors=new List<float>();
 for(int i=0;i<=512;i++){float z=-160+i*.625f;errors.Add(Mathf.Abs(H(near,-192,z)-H(mid,-192,z)));errors.Add(Mathf.Abs(H(near,192,z)-H(mid,192,z)));float x=-192+i*.75f;errors.Add(Mathf.Abs(H(near,x,-160)-H(mid,x,-160)));errors.Add(Mathf.Abs(H(near,x,160)-H(mid,x,160)));}
 for(int i=0;i<=256;i++){float z=-640+i*5;errors.Add(Mathf.Abs(H(mid,-768,z)-H(far,-768,z)));errors.Add(Mathf.Abs(H(mid,768,z)-H(far,768,z)));float x=-768+i*6;errors.Add(Mathf.Abs(H(mid,x,-640)-H(far,x,-640)));errors.Add(Mathf.Abs(H(mid,x,640)-H(far,x,640)));}
 var root=GameObject.Find("F1_VL_LiftAssembly").transform;var dynamicParts=new[]{root.Find("Car"),root.Find("Counterweight"),root.Find("Sheave"),root.Find("Ropes"),root.Find("FixedShaft/LandingDoorLeft"),root.Find("FixedShaft/LandingDoorRight")};var staticMoving=dynamicParts.SelectMany(t=>t.GetComponentsInChildren<Renderer>(true)).Where(r=>(GameObjectUtility.GetStaticEditorFlags(r.gameObject)&(StaticEditorFlags.OccluderStatic|StaticEditorFlags.BatchingStatic))!=0).Select(r=>r.name).ToArray();
 var result=new{scene=s.path,saved=!s.isDirty,playing=Application.isPlaying,transforms=ts.Length,colliders=ts.Sum(t=>t.GetComponents<Collider>().Length),missingScripts=ts.Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)),missingMeshes=ts.SelectMany(t=>t.GetComponents<MeshFilter>()).Count(f=>!f.sharedMesh),missingMaterials=ts.SelectMany(t=>t.GetComponents<Renderer>()).Count(r=>r.sharedMaterials.Any(m=>!m||!m.shader)),seamSamples=errors.Count,maxSeamError=errors.Max(),movingPartsIncorrectlyStatic=staticMoving,occlusionBytes=StaticOcclusionCulling.umbraDataSize,occlusionGUID=AssetDatabase.AssetPathToGUID("Assets/Afrer_Seconds/01.Scenes/Stage/Level_1F_Factory/OcclusionCullingData.asset"),runInBackground=Application.runInBackground};File.WriteAllText(Path.GetFullPath(Application.dataPath+"/../../../Docs/Review/2026-11-13_1F_RoofLiftWilderness/final_check.json"),JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
